def solve(inputs):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a, m)
        if gcd != 1:
            raise ValueError("Inverse doesn't exist")
        else:
            return x % m

    def chinese_remainder_theorem(remainders, moduli):
        N = 1
        for modulus in moduli:
            N *= modulus

        x = 0
        for remainder, modulus in zip(remainders, moduli):
            Ni = N // modulus
            Ni_inverse = mod_inverse(Ni, modulus)
            x += remainder * Ni * Ni_inverse

        return x % N

    remainders = [inputs['R1'], inputs['R2'], inputs['R3'], inputs['R4']]
    moduli = [inputs['M1'], inputs['M2'], inputs['M3'], inputs['M4']]

    return chinese_remainder_theorem(remainders, moduli)

